xpath.script:
(function () {
    const theme = localStorage.getItem("lhi_theme") || "system";
    let isDark = false;
    if (theme === "dark") {
        isDark = true;
    } else if (theme === "system") {
        isDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
    }
    const themeVal = isDark ? "dark" : "light";
    document.documentElement.setAttribute("data-lhi-theme", themeVal);
    document.documentElement.setAttribute("data-bs-theme", themeVal);
})();
